# Essential imports (guaranteed to be available)
import os
import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.optim as optim
from data_loader import build_train_val_dataloaders
import json
from tqdm import tqdm
import numpy as np
from sklearn.metrics import roc_auc_score

from torch.utils.data import DataLoader
from torch.cuda.amp import GradScaler, autocast

# Define constants
NUM_SPECIES = 206
BATCH_SIZE = 16
LEARNING_RATE = 0.0001
MAX_EPOCHS = 50
EARLY_STOPPING_PATIENCE = 5

# Determine architecture depth based on iteration number
ITERATION_NUMBER = 161  # Example iteration number
if ITERATION_NUMBER % 3 == 0:
    num_conv_layers = 2
elif ITERATION_NUMBER % 3 == 1:
    num_conv_layers = 3
else:
    num_conv_layers = 4

# Define the model architecture
class BirdClassifier(nn.Module):
    def __init__(self, num_classes=NUM_SPECIES, dropout_rate=0.2):
        super(BirdClassifier, self).__init__()
        layers = []
        in_channels = 1  # Assuming mono audio input
        out_channels = 32
        
        for i in range(num_conv_layers):
            layers.append(nn.Conv2d(in_channels, out_channels, kernel_size=3, stride=1, padding=1))
            layers.append(nn.BatchNorm2d(out_channels))
            layers.append(nn.ReLU())
            layers.append(nn.MaxPool2d(kernel_size=2, stride=2))
            in_channels = out_channels
            out_channels *= 2
        
        self.features = nn.Sequential(*layers)
        self.avg_pool = nn.AdaptiveAvgPool2d((1, 1))
        self.classifier = nn.Sequential(
            nn.Linear(in_channels * 1 * 1, 512),
            nn.ReLU(),
            nn.Dropout(dropout_rate),
            nn.Linear(512, num_classes)
        )
    
    def forward(self, x):
        x = self.features(x)
        x = self.avg_pool(x)
        x = torch.flatten(x, 1)
        x = self.classifier(x)
        return x

# Load data (assuming get_dataloader() is defined elsewhere)
train_loader = DataLoader(dataset=None, batch_size=BATCH_SIZE, shuffle=True)  # Replace with actual dataset
val_loader = DataLoader(dataset=None, batch_size=BATCH_SIZE, shuffle=False)   # Replace with actual dataset

# Initialize model, optimizer, criterion, and scaler
model = BirdClassifier(num_classes=NUM_SPECIES, dropout_rate=0.2).to('cuda')
criterion = nn.BCEWithLogitsLoss()
optimizer = optim.Adam(model.parameters(), lr=LEARNING_RATE, weight_decay=0.001)
scaler = GradScaler("cuda")

# Learning rate scheduler
scheduler = optim.lr_scheduler.ReduceLROnPlateau(optimizer, mode='max', patience=3)

# Training loop
best_auc = 0
early_stopping_counter = 0

for epoch in range(MAX_EPOCHS):
    model.train()
    train_loss = 0.0
    
    for batch_idx, (inputs, labels) in enumerate(train_loader):
        inputs, labels = inputs.to('cuda'), labels.to('cuda')
        
        optimizer.zero_grad()
        
        with autocast("cuda"):
            outputs = model(inputs)
            loss = criterion(outputs, labels)
        
        scaler.scale(loss).backward()
        scaler.step(optimizer)
        scaler.update()
        
        train_loss += loss.item()
    
    avg_train_loss = train_loss / len(train_loader)
    print(f"Epoch {epoch+1}/{MAX_EPOCHS}, Train Loss: {avg_train_loss:.4f}")
    
    # Validation
    model.eval()
    all_preds = []
    all_labels = []
    
    with torch.no_grad():
        for inputs, labels in val_loader:
            inputs, labels = inputs.to('cuda'), labels.to('cuda')
            
            outputs = model(inputs)
            preds = torch.sigmoid(outputs).cpu().numpy()
            all_preds.extend(preds)
            all_labels.extend(labels.cpu().numpy())
    
    all_preds = np.array(all_preds)
    all_labels = np.eye(NUM_SPECIES)[all_labels]  # One-hot encoding
    
    val_auc = roc_auc_score(all_labels, all_preds, multi_class='ovr')
    print(f"Epoch {epoch+1}/{MAX_EPOCHS}, Val AUC: {val_auc:.4f}")
    
    # Scheduler step
    scheduler.step(val_auc)
    
    # Early stopping
    if val_auc > best_auc:
        best_auc = val_auc
        early_stopping_counter = 0
        torch.save(model.state_dict(), 'model.pt')
    else:
        early_stopping_counter += 1
        if early_stopping_counter >= EARLY_STOPPING_PATIENCE:
            print("Early stopping triggered.")
            break

# Save metrics
metrics = {
    "final_train_loss": avg_train_loss,
    "final_auc": best_auc,
    "num_params": sum(p.numel() for p in model.parameters()),
    "epochs_trained": epoch + 1,
    "batch_size": BATCH_SIZE,
    "training_samples": len(train_loader.dataset),
    "eval_samples": len(val_loader.dataset)
}

print("METRICS: ", json.dumps(metrics))
with open('metrics.json', 'w') as f:
    json.dump(metrics, f)